mapper.sql:
with job as ( with t as ( select job_id, sum(case when status = 'INIT' then 1 else 0 END) as init, sum(case when status = 'DONE' then 1 else 0 END) as done, sum(case when status like '%DOING' then 1 else 0 END) as doing, sum(case when status like '%FAILED' then 1 else 0 END) as failed from task
deleted=0
and db_name=#{dbName}
and schema_name=#{schemaName}
and table_name=#{tableName}
and odps_project=#{dstOdpsProject}
and odps_schema=#{dstOdpsSchema}
and odps_table=#{dstOdpsTable}
and id in ( select task_id from task_partition where partition_id in (select id from partition_model where `value` like CONCAT('%', #{ptValue}, '%')) )
group by job_id ) select id, `description`, `source_name`, `db_name`, `odps_project`, `odps_schema`, `type`, `stopped`, `restart`, `timer`, `last_batch`, `config`, `deleted`, `create_time` datetime , t.init as tasks_init, t.done as tasks_done, t.doing as tasks_doing, t.failed as tasks_failed, ( case when t.doing > 0 then 'DOING' when t.failed > 0 then 'FAILED' when t.done > 0 and t.init = 0 then 'DONE' else 'INIT' end ) as status from job left join t on job.id = t.job_id )

mapper.select:

select * from job


order by id desc

    limit #{offset}, #{pageSize}

select id, job_id as jobId, batch_id as batchId, status, err_msg as errMsg, create_time as createTime
from job_batch
where job_id=#{jobId}
